"""Dependency-free offline HTML atlas; charts use the audited PNG artifacts."""
from __future__ import annotations
from html import escape
import json
import os
from pathlib import Path
import subprocess
from urllib.parse import quote
from .catalog import PROJECTS, TITLES, REPORTS, STAGES

REPO_URL = "https://github.com/songsiyi2006-chem/ai4pharm-lead-developability-suite/blob/main"


def write_navigation(out: Path, records: list, repo: Path, mode: str, source_root: Path | None = None):
    source_root = source_root or repo
    commit = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=repo, text=True).strip()
    archived_base = REPO_URL.removesuffix("main")+commit
    def source_url(name):
        # New simulations must open their actual data, never the archived main branch.
        if mode == "archived" and source_root.resolve() == repo.resolve():
            return archived_base+"/"+quote(name, safe="/")
        return quote(Path(os.path.relpath(source_root/name, out)).as_posix(), safe="/")
    cards = []
    for record in sorted(records, key=lambda r: r["task"]):
        i = record["task"]-1
        title = TITLES[i]
        panels = "".join(f"<li>{escape(str(panel))}</li>" for panel in record["panels"])
        sources = "".join(f'<li><a href="{escape(source_url(source), quote=True)}">{escape(Path(source).name)}</a></li>' for source in record["sources"])
        image = f'figures_omnibus/{record["file"]}'
        href = f"{REPO_URL}/projects/{PROJECTS[i]}"
        boundary = escape(record["evidence_boundary"])
        cards.append(f'''<article class="task" id="task{i+1}" data-stage="{STAGES[i]}">
<div class="task-head"><span class="number">{i+1:02d}</span><div><div class="eyebrow">{STAGES[i].upper()} / COMPUTATIONAL STUDY</div><h2>{escape(title)}</h2></div></div>
<button class="chart" data-image="{escape(image)}" aria-label="放大 Task {i+1} 综合图"><img src="{escape(image)}" loading="lazy" alt="Task {i+1}: {escape('; '.join(map(str, record['panels'])), quote=True)}"><span>查看完整图 ↗</span></button>
<div class="task-body"><p class="boundary"><span>证据边界</span>{boundary}</p><ul class="panels">{panels}</ul>
<div class="links"><a href="{href}/README.md">项目与代码 ↗</a><a href="{href}/{REPORTS[i]}_ZH.md">中文报告</a><a href="{href}/{REPORTS[i]}_EN.md">English</a></div>
<details><summary>数据来源与图表溯源 · {len(record['sources'])} files</summary><ul class="sources">{sources}</ul><p class="hash">Figure SHA256<br>{record['sha256']}</p></details></div></article>''')
    mode_label = {"archived": "归档计算结果重绘", "recompute": "本机新计算结果", "provided_source_tree": "指定输入树重绘（执行记录另行核验）"}[mode]
    template = '''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI4Pharm · Decade Atlas</title><style>
:root{--ink:#122b3c;--muted:#506672;--paper:#f4f4ee;--line:#d8dfdc;--teal:#007b73;--white:#fff;--orange:#ae530f}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,"Segoe UI","Microsoft YaHei",sans-serif;line-height:1.6}a{color:var(--teal);text-underline-offset:4px}button,input{font:inherit}button,a,input,summary{outline-offset:5px}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #bd671d}.top{max-width:1460px;margin:auto;padding:24px 4%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:16px}.brand{font-weight:800;letter-spacing:.06em;font-size:19px}.brand small{font-weight:400;letter-spacing:0;margin-left:14px;color:var(--muted)}.repo{text-decoration:none;font-size:14px}.hero{max-width:1460px;margin:auto;padding:66px 4% 46px;display:grid;grid-template-columns:1.6fr 1fr;gap:50px;align-items:center}.eyebrow{font-size:11px;letter-spacing:.15em;color:var(--teal);font-weight:700}.hero h1{font-size:clamp(35px,4vw,62px);line-height:1.16;margin:14px 0 24px;font-weight:700;letter-spacing:-.05em}.hero h1 em{font-style:normal;color:var(--teal)}.intro{max-width:650px;color:var(--muted);font-size:16px}.hero-links{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.pill{display:inline-block;border:1px solid var(--line);border-radius:5px;text-decoration:none;padding:9px 15px;background:white;font-size:14px}.pill.primary{background:var(--ink);color:white;border-color:var(--ink)}.map{background:var(--ink);color:#eef8f5;border-radius:12px;padding:28px;box-shadow:10px 10px 0 #d8e9e3}.map .eyebrow{color:#8dd7c1}.map-row{display:flex;align-items:center;justify-content:space-between;padding:17px 0;border-bottom:1px solid #34525e;font-size:14px;gap:12px}.map-row:last-of-type{border-bottom:0}.map-row a{color:#9ae7cf;text-decoration:none;font-size:13px}.map small{display:block;color:#b2c8cf;line-height:1.6;margin-top:14px}.metrics{display:flex;gap:22px;flex-wrap:wrap;margin-top:23px;font-size:12px;color:var(--muted)}.metrics strong{font-size:24px;color:var(--ink);margin-right:5px}.workspace{max-width:1460px;margin:auto;padding:0 4% 70px}.controls{position:sticky;top:0;z-index:4;background:rgba(244,244,238,.98);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0;margin-bottom:24px;display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}.filters{display:flex;gap:6px;flex-wrap:wrap}.filters button{border:0;padding:7px 12px;border-radius:4px;cursor:pointer;background:transparent;color:var(--muted);font-size:13px}.filters button[aria-pressed=true]{background:var(--ink);color:white}input[type=search]{width:240px;max-width:100%;border:1px solid #a8b8b5;border-radius:4px;background:white;padding:8px 11px;font-size:13px}.result-count{font-size:12px;color:var(--muted);margin:0 0 14px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:25px}.task{background:white;border:1px solid var(--line);border-radius:9px;overflow:hidden;scroll-margin-top:95px}.task[hidden]{display:none}.task-head{display:flex;align-items:center;gap:16px;padding:23px 25px 15px}.number{color:#a8bfbb;font-size:36px;line-height:1;font-weight:300}.task h2{font-size:18px;margin:3px 0 0;font-weight:650}.task .eyebrow{font-size:9px}.chart{position:relative;border:0;border-top:1px solid #edf0ef;border-bottom:1px solid #edf0ef;background:white;padding:8px;width:100%;cursor:zoom-in;display:block}.chart img{width:100%;height:225px;object-fit:contain;display:block}.chart span{position:absolute;right:12px;bottom:10px;padding:3px 8px;background:#eef4f1;color:var(--teal);font-size:10px;border-radius:3px}.task-body{padding:18px 25px 23px}.boundary{margin:0;color:#536977;font-size:12px;min-height:57px}.boundary span{font-weight:700;color:var(--orange);display:block;margin-bottom:4px}.panels{font-size:12px;padding-left:17px;color:var(--muted);min-height:64px}.panels li{margin:2px 0}.links{display:flex;gap:18px;flex-wrap:wrap;padding:12px 0 16px;font-size:12px}.links a{text-decoration:none}details{border-top:1px solid var(--line);padding-top:12px;font-size:11px;color:var(--muted)}summary{cursor:pointer}.sources{padding-left:17px;overflow-wrap:anywhere}.hash{overflow-wrap:anywhere;font:10px/1.6 monospace;background:#f7f8f7;padding:10px}.empty{padding:30px;background:white;border:1px solid var(--line);text-align:center}.reproduce{background:#e8efeb;margin-top:36px;border:1px solid #d0dcd6;border-radius:8px;padding:25px 28px}.reproduce h2{font-size:20px;margin:0 0 8px}.reproduce p{font-size:13px;color:var(--muted)}pre{background:var(--ink);color:#edf9f2;border-radius:5px;padding:18px;overflow-x:auto;font-size:12px;line-height:1.8}footer{max-width:1460px;margin:auto;padding:22px 4%;border-top:1px solid var(--line);font-size:12px;color:var(--muted);display:flex;gap:15px;justify-content:space-between;flex-wrap:wrap}dialog{border:0;padding:0;border-radius:8px;max-width:96vw;width:1500px;max-height:95vh;background:white}dialog::backdrop{background:#102331df}.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:10px 18px;font-size:13px}.dialog-head button{background:var(--ink);color:white;border:0;border-radius:4px;padding:6px 14px;cursor:pointer}dialog img{display:block;width:100%;max-height:83vh;object-fit:contain}dialog a{font-size:12px}body:has(dialog[open]){overflow:hidden} @media(max-width:850px){.hero{grid-template-columns:1fr;padding-top:35px;gap:28px}.grid{grid-template-columns:1fr}.map{box-shadow:5px 5px 0 #d8e9e3}.brand small{display:none}.chart img{height:auto}.hero h1{letter-spacing:-.03em}.task-head,.task-body{padding-left:18px;padding-right:18px}.controls{position:static}.boundary,.panels{min-height:0}}@media print{.controls,.chart span,dialog{display:none}.grid{display:block}.task{break-inside:avoid;margin-bottom:20px}.hero{padding-top:20px}.chart img{height:230px}.map{box-shadow:none}.reproduce{break-inside:avoid}}
</style></head><body>
<header class="top"><div class="brand">AI4Pharm <small>DECADE ATLAS · 十维研究图谱</small></div><a class="repo" href="__REPO__">GitHub Repository ↗</a></header>
<section class="hero"><div><div class="eyebrow">FROM MOLECULE TO TRANSLATIONAL QUESTIONS</div><h1>十个研究视角。<br><em>一张可追溯的图谱。</em></h1><p class="intro">从先导性质、作用机制与体内暴露，到制剂、联合治疗、ADC 和 RNA。每张图都连接实际计算数据、方法与报告，让研究结果和证据缺口同样清楚。</p><div class="hero-links"><a class="pill primary" href="__BLOB__/AI4PHARM_DECADE_TREATISE_ZH.md">中文总报告 ↗</a><a class="pill" href="__BLOB__/AI4PHARM_DECADE_TREATISE_EN.md">English treatise ↗</a><a class="pill" href="#reproduce">本机复现</a></div><div class="metrics"><span><strong>10</strong> 计算项目</span><span><strong>10</strong> 综合图</span><span><strong>300</strong> DPI</span><span><strong>2</strong> 总报告语言</span></div></div>
<aside class="map" aria-label="研究架构"><div class="eyebrow">STUDY ARCHITECTURE</div><div class="map-row"><span>01–03 · 先导与作用机制</span><a href="#task1">Discovery ↘</a></div><div class="map-row"><span>04–06 · 暴露、相互作用与制剂</span><a href="#task4">Exposure ↘</a></div><div class="map-row"><span>07–08 · 系统药理与 ADC</span><a href="#task7">Response ↘</a></div><div class="map-row"><span>09–10 · 结构变构与 RNA</span><a href="#task9">Structure ↘</a></div><small>已执行模型调用：Task 4 → Task 5。<br>其他项目分别建模，跨尺度参数传递仍需实验校准。</small></aside></section>
<main class="workspace"><div class="controls"><div class="filters" aria-label="研究阶段筛选"><button data-filter="all" aria-pressed="true">全部 / All</button><button data-filter="discovery" aria-pressed="false">先导与机制</button><button data-filter="exposure" aria-pressed="false">暴露与制剂</button><button data-filter="response" aria-pressed="false">系统响应</button><button data-filter="structure" aria-pressed="false">结构与 RNA</button></div><label><span class="eyebrow">FIND </span><input id="search" type="search" placeholder="搜索任务、方法或证据…" aria-label="搜索任务、方法或证据"></label></div><p id="count" class="result-count" aria-live="polite">显示 10 / 10 个项目 · __MODE__</p><div class="grid">__CARDS__</div><p class="empty" id="empty" hidden>没有匹配的项目。清空搜索或选择「全部」。</p>
<section class="reproduce" id="reproduce"><div class="eyebrow">LOCAL CPU · REPRODUCIBLE WORKFLOW</div><h2>从数据到图表，都有独立入口。</h2><p>已有依赖环境中，在仓库根目录执行。归档模式重新绘图；复算模式顺序执行全部十项计算，数值库限制为单线程，输出必须使用新目录。</p><pre><code># Rebuild from archived numerical data
python run_ai4pharm_omnibus_suite.py --out work/omnibus

# Recompute the ten studies on a local CPU, then rebuild the atlas
python run_ai4pharm_omnibus_suite.py --mode recompute --out work/omnibus_fresh</code></pre><p><a href="data_omnibus/figure_provenance.json">图表与输入溯源</a> · <a href="data_omnibus/source_hashes.json">输入 SHA256</a> · <a href="data_omnibus/run_summary.json">运行记录</a> · <a href="manifest_omnibus.json">产物校验清单</a></p><p>此页无需在线库即可交互与查看本地图片；项目代码和报告链接指向 GitHub。模型输出保留假设、代理与缺失状态，软件检查不构成生物学或临床验证。</p></section></main>
<footer><span>AI4Pharm · Translational Developability Suite</span><span>Public structures · Executed calculations · Explicit assumptions</span></footer>
<dialog id="viewer"><div class="dialog-head"><a id="original" href="#" target="_blank" rel="noopener">打开原始 300 DPI 图 ↗</a><button id="close">关闭 / Close</button></div><img id="large" alt=""></dialog>
<script>
const cards=[...document.querySelectorAll('.task')],buttons=[...document.querySelectorAll('[data-filter]')],search=document.querySelector('#search');let active='all';
function filter(){let n=0;const q=search.value.toLocaleLowerCase().trim();cards.forEach(c=>{const show=(active==='all'||c.dataset.stage===active)&&c.textContent.toLocaleLowerCase().includes(q);c.hidden=!show;if(show)n++;});document.querySelector('#count').textContent=`显示 ${n} / 10 个项目 · __MODE__`;document.querySelector('#empty').hidden=n>0;}
buttons.forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter();}));search.addEventListener('input',filter);
const viewer=document.querySelector('#viewer');document.querySelectorAll('.chart').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#large').src=b.dataset.image;document.querySelector('#large').alt=b.querySelector('img').alt;document.querySelector('#original').href=b.dataset.image;viewer.showModal();}));document.querySelector('#close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close();});
document.querySelectorAll('.map-row a').forEach(a=>a.addEventListener('click',()=>{active='all';search.value='';buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));filter();}));
</script></body></html>
'''
    content = template.replace("__REPO__", REPO_URL.removesuffix("/blob/main")).replace("__BLOB__", REPO_URL)
    content = content.replace("__CARDS__", "\n".join(cards)).replace("__MODE__", escape(mode_label))
    (out/"index.html").write_text(content, encoding="utf-8", newline="\n")
